import java.util.*;

class Solution {
  public int findBlackPixel(char[][] picture, int target) {
    int m = picture.length, n = picture[0].length;
    int[] cols = new int[n];
    Map<String, Integer> rowPattern = new HashMap<>(); // rows with exactly target blacks, by content
    for (char[] row : picture) {
      int blacks = 0;
      for (int j = 0; j < n; j++)
        if (row[j] == 'B') {
          blacks++;
          cols[j]++;
        }
      if (blacks == target) rowPattern.merge(new String(row), 1, Integer::sum);
    }
    // a column qualifies when all target rows holding its blacks are this identical row
    int count = 0;
    for (Map.Entry<String, Integer> e : rowPattern.entrySet()) {
      if (e.getValue() != target) continue;
      String row = e.getKey();
      for (int j = 0; j < n; j++) if (row.charAt(j) == 'B' && cols[j] == target) count += target;
    }
    return count;
  }
}
